import {reactive, SetupContext} from 'features/compositionApi';
import axios from 'axios';

interface BackendServiceState {
    serviceEndpoint: string;
    pingInterval: number;
    pingIntervalId: ReturnType<typeof setInterval> | null;
}

export const usePingLimitService = (props: {}, context: SetupContext) => {
    const state = reactive<BackendServiceState>({
        serviceEndpoint: 'service-api/LimitService',
        pingInterval: 30 * 1000, // 30 seconds
        pingIntervalId: null,
    });

    const ping = async (): Promise<null> => {
        const response = await axios.get(`${state.serviceEndpoint}/Ping`);
        return response.data;
    };

    const startPingInterval = () => {
        stopPingInterval();
        state.pingIntervalId = setInterval(() => {
            ping();
        }, state.pingInterval);
    };

    const stopPingInterval = () => {
        if (state.pingIntervalId != null) {
            clearInterval(state.pingIntervalId);
            state.pingIntervalId = null;
        }
    };


    const stop = () => {
        stopPingInterval();
    };

    return {
        startPingInterval,
        stop,
    }
};

